  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--color-danger);
}

.modal-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: 10px;
  letter-spacing: -0.3px;
}

.modal-body {
  font-size: 15px;
  line-height: 1.55;
  color: var(--color-text-secondary);
  margin-bottom: 28px;
}

.modal-body strong {
  color: var(--color-text);
  font-weight: 600;
}

.modal-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

.modal-close-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: #f0f0f5;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-secondary);
  transition: background var(--transition), color var(--transition);
  font-family: inherit;
}

.modal-close-btn:hover {
  background: #e5e5ea;
  color: var(--color-text);
}

.modal-close-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
