+(function () {
+  'use strict';
+
+  const overlay  = document.getElementById('deleteModal');
+  const trigger  = document.querySelector('.trigger');
+  const cancelBtn = document.getElementById('cancelDelete');
+  const confirmBtn = document.getElementById('confirmDelete');
+  const closeBtn = document.getElementById('modalClose');
+
+  // Elements to keep focus trapped inside the dialog
+  const focusableSelectors = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
+
+  function openModal() {
+    overlay.classList.add('is-open');
+    overlay.removeAttribute('aria-hidden');
+    // Move focus to the first focusable element in the dialog
+    const firstFocusable = overlay.querySelector(focusableSelectors);
+    if (firstFocusable) firstFocusable.focus();
+    document.body.style.overflow = 'hidden';
+  }
+
+  function closeModal() {
+    overlay.classList.remove('is-open');
+    overlay.setAttribute('aria-hidden', 'true');
+    document.body.style.overflow = '';
+    trigger.focus(); // return focus to trigger
+  }
+
+  // Trap focus within the modal while it is open
+  function trapFocus(e) {
+    if (!overlay.classList.contains('is-open')) return;
+    const focusable = Array.from(overlay.querySelectorAll(focusableSelectors));
+    const first = focusable[0];
+    const last  = focusable[focusable.length - 1];
+
+    if (e.key === 'Tab') {
+      if (e.shiftKey) {
+        if (document.activeElement === first) {
+          e.preventDefault();
+          last.focus();
+        }
+      } else {
+        if (document.activeElement === last) {
+          e.preventDefault();
+          first.focus();
+        }
+      }
+    }
+
+    if (e.key === 'Escape') {
+      closeModal();
+    }
+  }
+
+  trigger.addEventListener('click', openModal);
+  cancelBtn.addEventListener('click', closeModal);
+  closeBtn.addEventListener('click', closeModal);
+
+  // Close on backdrop click
+  overlay.addEventListener('click', function (e) {
+    if (e.target === overlay) closeModal();
+  });
+
+  document.addEventListener('keydown', trapFocus);
+
+  confirmBtn.addEventListener('click', function () {
+    // Simulate deletion feedback
+    confirmBtn.textContent = 'Deleting…';
+    confirmBtn.disabled = true;
+    setTimeout(function () {
+      closeModal();
+      // Reset button state after modal closes
+      confirmBtn.textContent = 'Delete image';
+      confirmBtn.disabled = false;
+      // Show a brief toast / inline feedback
+      showToast('Image deleted from your library.');
+    }, 900);
+  });
+
+  function showToast(message) {
+    const toast = document.createElement('div');
+    toast.setAttribute('role', 'status');
+    toast.setAttribute('aria-live', 'polite');
+    toast.className = 'toast';
+    toast.textContent = message;
+    document.body.appendChild(toast);
+
+    // Animate in
+    requestAnimationFrame(function () {
+      requestAnimationFrame(function () {
+        toast.classList.add('toast--visible');
+      });
+    });
+
+    setTimeout(function () {
+      toast.classList.remove('toast--visible');
+      toast.addEventListener('transitionend', function () { toast.remove(); }, { once: true });
+    }, 3000);
+  }
+}());
